package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.ObjectBuffer;
import com.fasterxml.jackson.databind.deser.std.JsonDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class StringArrayDeserializer__deserializeCustom_TriageGen1Test {

    private StringArrayDeserializer deserializer;
    private JsonParser jp;
    private DeserializationContext ctxt;
    private ObjectBuffer buffer;
    private JsonDeserializer<String> elementDeserializer;

    // Subclass to expose the protected method for testing
    private static class TestableStringArrayDeserializer extends StringArrayDeserializer {
        @Override
        public String[] deserialize(JsonParser jp, DeserializationContext ctxt) throws IOException {
            return _deserializeCustom(jp, ctxt);
        }

        // We need a way to inject the element deserializer because it's private/protected in real Jackson
        // For the purpose of this unit test, we use reflection or a setter if available.
        // Since we cannot modify the source, we simulate the state via Mockito or Reflection.
        public void setElementDeserializer(JsonDeserializer<String> deser) throws Exception {
            java.lang.reflect.Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
            field.setAccessible(true);
            field.set(this, deser);
        }
    }

    @Before
    public void setUp() throws Exception {
        deserializer = new TestableStringArrayDeserializer();
        jp = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
        buffer = mock(ObjectBuffer.class);
        elementDeserializer = mock(JsonDeserializer.class);

        deserializer.setElementDeserializer(elementDeserializer);

        when(ctxt.leaseObjectBuffer()).thenReturn(buffer);
        when(elementDeserializer.getNullValue()).thenReturn(null);
    }

    @Test
    public void testDeserializeEmptyArray() throws IOException {
        when(jp.nextToken()).thenReturn(JsonToken.END_ARRAY);
        Object[] chunk = new Object[1];
        when(buffer.resetAndStart()).thenReturn(chunk);
        when(buffer.completeAndClearBuffer(eq(chunk), eq(0), eq(String.class))).thenReturn(new String[0]);

        String[] result = deserializer.deserialize(jp, ctxt);

        assertEquals(0, result.length);
        Mockito.verify(ctxt).returnObjectBuffer(buffer);
    }

    @Test
    public void testDeserializeSingleElement() throws IOException {
        when(jp.nextToken())
                .thenReturn(JsonToken.START_ARRAY)
                .thenReturn(JsonToken.VALUE_STRING)
                .thenReturn(JsonToken.END_ARRAY);

        when(elementDeserializer.deserialize(eq(jp), eq(ctxt))).thenReturn("test");

        Object[] chunk = new Object[1];
        when(buffer.resetAndStart()).thenReturn(chunk);
        when(buffer.completeAndClearBuffer(eq(chunk), eq(1), eq(String.class))).thenReturn(new String[]{"test"});

        String[] result = deserializer.deserialize(jp, ctxt);

        assertArrayEquals(new String[]{"test"}, result);
        Mockito.verify(ctxt).returnObjectBuffer(buffer);
    }

    @Test
    public void testDeserializeWithNull() throws IOException {
        when(jp.nextToken())
                .thenReturn(JsonToken.START_ARRAY)
                .thenReturn(JsonToken.VALUE_NULL)
                .thenReturn(JsonToken.END_ARRAY);

        when(elementDeserializer.getNullValue()).thenReturn(null);

        Object[] chunk = new Object[1];
        when(buffer.resetAndStart()).thenReturn(chunk);
        when(buffer.completeAndClearBuffer(eq(chunk), eq(1), eq(String.class))).thenReturn(new String[]{null});

        String[] result = deserializer.deserialize(jp, ctxt);

        assertArrayEquals(new String[]{null}, result);
    }

    @Test
    public void testDeserializeWithBufferOverflow() throws IOException {
        // Force buffer overflow by providing a small chunk and multiple elements
        int chunkSize = 2;
        Object[] chunk1 = new Object[chunkSize];
        Object[] chunk2 = new Object[chunkSize];

        when(jp.nextToken())
                .thenReturn(JsonToken.START_ARRAY)
                .thenReturn(JsonToken.VALUE_STRING) // ix = 0
                .thenReturn(JsonToken.VALUE_STRING) // ix = 1
                .thenReturn(JsonToken.VALUE_STRING) // ix = 2 -> trigger append
                .thenReturn(JsonToken.END_ARRAY);

        when(elementDeserializer.deserialize(eq(jp), eq(ctxt)))
                .thenReturn("a")
                .thenReturn("b")
                .thenReturn("c");

        when(buffer.resetAndStart()).thenReturn(chunk1);
        // Mock the append process
        when(buffer.appendCompletedChunk(chunk1)).thenReturn(chunk2);
        // After append, ix resets to 0, so the 3rd element goes to chunk2[0]
        when(buffer.completeAndClearBuffer(eq(chunk2), eq(1), eq(String.class))).thenReturn(new String[]{"a", "b", "c"});

        String[] result = deserializer.deserialize(jp, ctxt);

        assertEquals(3, result.length);
        assertEquals("c", result[2]);
        Mockito.verify(buffer).appendCompletedChunk(chunk1);
        Mockito.verify(ctxt).returnObjectBuffer(buffer);
    }

    @Test(expected = IOException.class)
    public void testDeserializeThrowsIOException() throws IOException {
        when(jp.nextToken()).thenThrow(new IOException("Parser error"));

        when(buffer.resetAndStart()).thenReturn(new Object[1]);

        deserializer.deserialize(jp, ctxt);
    }
}
